fn is_integer(text: &Vec<char>) -> bool {
    // Check if all characters in the vector are digits
    // Requires: text must be a non-null reference to a vector of characters
    // Ensures: returns true if all characters are digits, false otherwise
    // Invariant: For all characters c in text, c.is_digit(10) is true if the result is true
    // Decreases: length of text
    assert!(text.len() >= 0); // Ensure the vector is not empty
    text.iter().all(|&c| c.is_digit(10))
}

